/* All content is already in the HTML (generated by build.js for each language).
   This script only brings it to life: intro, menu, scroll effects, player, gallery, cursor. */
(() => {
  "use strict";

  const $ = (s, el = document) => el.querySelector(s);
  const $$ = (s, el = document) => [...el.querySelectorAll(s)];
  const root = document.documentElement;
  const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const isDesktop = () => innerWidth > 960;
  const lang = I18N[root.lang] ? root.lang : "en";
  const ROOT = window.ROOT || "";

  const t = (k) => (I18N[lang] && I18N[lang][k]) ?? I18N.en[k] ?? "";
  const pad = (n) => String(n).padStart(2, "0");
  const clock = (s) => `${pad(Math.floor(s / 60))}:${pad(Math.floor(s % 60))}`;
  const store = (k, v) => { try { localStorage.setItem(k, v); } catch (e) { /* storage unavailable */ } };
  const read = (k) => { try { return localStorage.getItem(k); } catch (e) { return null; } };

  /* ======================================================================
     Language links — remember the choice and stay in the same section
     ====================================================================== */
  // Opened straight from disk (file://) there is no web server to turn "en/" into "en/index.html"
  const LOCAL = location.protocol === "file:";
  const page = (href) => (LOCAL && href.endsWith("/") ? href + "index.html" : href);
  $$("a[data-lang]").forEach((a) => { a.href = page(a.getAttribute("href")); });

  function currentSection() {
    let id = "";
    $$("main > section[id]").forEach((s) => { if (s.getBoundingClientRect().top < innerHeight * 0.4) id = s.id; });
    return id && id !== "top" ? "#" + id : "";
  }
  $$("a[data-lang]").forEach((a) => a.addEventListener("click", (e) => {
    store("lang", a.dataset.lang);
    if (a.dataset.lang === lang) { e.preventDefault(); closeMenu(); return; }
    try { sessionStorage.setItem("intro", "1"); } catch (err) { /* ignore */ }
    a.href = a.getAttribute("href").split("#")[0] + currentSection();
  }));

  // Croatian home page: offer EN/DE once to visitors whose browser speaks another language
  if (lang === "hr" && !read("lang")) {
    const nav = (navigator.language || "").slice(0, 2).toLowerCase();
    if (!["hr", "bs", "sr", "sl", "me"].includes(nav)) {
      const target = nav === "de" ? "de" : "en";
      const note = $("#langnote"), link = $("#langnoteLink");
      link.textContent = I18N[target].langnote;
      link.href = page(`${target}/`);
      link.setAttribute("hreflang", target);
      link.addEventListener("click", () => { store("lang", target); link.href = page(`${target}/`) + currentSection(); });
      $("#langnoteClose").addEventListener("click", () => { note.classList.remove("show"); store("lang", "hr"); });
      note.hidden = false;
      setTimeout(() => note.classList.add("show"), 2600);
    }
  }

  /* ======================================================================
     Intro — A tuned from 415 to 442 Hz while one bow stroke crosses the screen
     ====================================================================== */
  function runIntro(done) {
    if (root.classList.contains("no-intro")) { done(); return; }
    try { sessionStorage.setItem("intro", "1"); } catch (e) { /* ignore */ }
    const hz = $("#hz"), start = performance.now(), D = 1500;
    const step = (now) => {
      const p = Math.min(1, (now - start) / D);
      hz.textContent = Math.round(415 + 27 * (1 - Math.pow(1 - p, 3)));
      if (p < 1) requestAnimationFrame(step);
      else setTimeout(() => { $("#intro").classList.add("done"); setTimeout(done, 250); }, 250);
    };
    requestAnimationFrame(step);
  }

  /* split the hero name into letters for the entrance (the h1 keeps a readable label) */
  const h1 = $(".hero__name");
  h1.setAttribute("aria-label", h1.textContent.replace(/\s+/g, " ").trim());
  $$("[data-split]").forEach((el) => {
    const delay = el.classList.contains("hero__word--it") ? 0.25 : 0;
    el.innerHTML = [...el.textContent].map((c, i) =>
      `<span class="ch" aria-hidden="true"><span style="transition-delay:${(0.05 + i * 0.045 + delay).toFixed(3)}s">${c}</span></span>`).join("");
  });

  /* ======================================================================
     Header & programme menu
     ====================================================================== */
  const head = $("#head");
  const navLinks = $$(".head__nav a");
  const targets = navLinks.map((a) => $(a.getAttribute("href")));
  let lastY = 0;

  function openMenu() { document.body.classList.add("menu-open"); $("#menuBtn").setAttribute("aria-expanded", "true"); $("#programme").setAttribute("aria-hidden", "false"); }
  function closeMenu() { document.body.classList.remove("menu-open"); $("#menuBtn").setAttribute("aria-expanded", "false"); $("#programme").setAttribute("aria-hidden", "true"); }
  $("#menuBtn").addEventListener("click", () => document.body.classList.contains("menu-open") ? closeMenu() : openMenu());
  $$("#programme a[href^='#']").forEach((a) => a.addEventListener("click", closeMenu));

  /* ======================================================================
     Statement — words light up as you read
     ====================================================================== */
  const statement = $("#statementText");
  const words = $$(".w", statement);
  function updateStatement() {
    const r = statement.getBoundingClientRect();
    const p = (innerHeight * 0.82 - r.top) / (r.height + innerHeight * 0.25);
    const lit = Math.round(Math.max(0, Math.min(1, p)) * words.length);
    words.forEach((w, i) => w.classList.toggle("on", i < lit));
  }

  /* ======================================================================
     Timeline (horizontal, pinned on desktop)
     ====================================================================== */
  const tlWrap = $("#timeline"), tlTrack = $("#timelineTrack");
  const tlItems = $$(".tl", tlTrack);
  function sizeTimeline() {
    if (!isDesktop()) { tlWrap.style.height = ""; tlTrack.style.transform = ""; return; }
    tlWrap.style.height = `${innerHeight + Math.max(0, tlTrack.scrollWidth - innerWidth)}px`;
  }
  function updateTimeline() {
    if (isDesktop()) {
      const r = tlWrap.getBoundingClientRect();
      const dist = tlTrack.scrollWidth - innerWidth;
      const p = Math.max(0, Math.min(1, -r.top / Math.max(1, r.height - innerHeight)));
      tlTrack.style.transform = `translate3d(${(-p * dist).toFixed(1)}px,0,0)`;
      $("#timelineProgress").style.transform = `scaleX(${p})`;
      tlItems.forEach((el) => el.classList.toggle("on", el.getBoundingClientRect().left < innerWidth * 0.62 && r.top < innerHeight * 0.5));
    } else {
      tlItems.forEach((el) => el.classList.toggle("on", el.getBoundingClientRect().top < innerHeight * 0.72));
    }
  }

  /* ======================================================================
     Biography — full text is in the HTML, folded until opened
     ====================================================================== */
  const bioToggle = $("#bioToggle"), bioFull = $("#bioFull");
  bioFull.hidden = true;
  bioToggle.addEventListener("click", () => {
    const open = bioToggle.getAttribute("aria-expanded") !== "true";
    bioToggle.setAttribute("aria-expanded", String(open));
    bioFull.hidden = !open;
    $(".bio__toggle-label").textContent = t(open ? "bio.close" : "bio.read");
    requestAnimationFrame(sizeTimeline);
  });

  /* ======================================================================
     Concerts — the page may be older than today: move passed dates to the archive
     ====================================================================== */
  (function concerts() {
    const today = new Date();
    const iso = `${today.getFullYear()}-${pad(today.getMonth() + 1)}-${pad(today.getDate())}`;
    const up = $("#upcoming"), past = $("#past");
    const moved = $$("li[data-date]", up).filter((li) => li.dataset.date < iso);
    if (!moved.length) return;
    moved.reverse().forEach((li) => past.prepend(li));
    $(".concerts__past").hidden = false;
    if (!$("li[data-date]", up)) {
      up.innerHTML = `<li class="empty">${t("concerts.empty")}<br><a href="#coda">${t("concerts.booking")} →</a></li>`;
    }
  })();

  /* ======================================================================
     III. Audio — circular waveform ("the disc")
     ====================================================================== */
  const Disc = (() => {
    const audio = $("#player");
    const canvas = $("#discCanvas");
    const ctx = canvas.getContext("2d");
    const items = $$("#tracklist li");
    let cur = 0, loaded = -1, raf = 0, size = 0, dpr = 1;

    function resize() {
      dpr = Math.min(2, devicePixelRatio || 1);
      size = canvas.clientWidth;
      canvas.width = canvas.height = Math.round(size * dpr);
      draw(performance.now());
    }

    function draw(now) {
      const peaks = (PEAKS[TRACKS[cur].id] || { peaks: [] }).peaks;
      const N = peaks.length || 120;
      const progress = loaded === cur && audio.duration ? audio.currentTime / audio.duration : 0;
      const playing = loaded === cur && !audio.paused;
      const s = size * dpr, c = s / 2;
      const r0 = s * 0.285, maxL = s * 0.17, ring = r0 + maxL + 18 * dpr;
      ctx.clearRect(0, 0, s, s);
      ctx.lineCap = "round";

      // outer measuring ring with 60 ticks
      ctx.strokeStyle = "rgba(236,233,226,.14)";
      ctx.lineWidth = dpr;
      ctx.beginPath(); ctx.arc(c, c, ring, 0, Math.PI * 2); ctx.stroke();
      for (let i = 0; i < 60; i++) {
        const a = -Math.PI / 2 + (i / 60) * Math.PI * 2, L = (i % 5 ? 4 : 9) * dpr;
        ctx.beginPath();
        ctx.moveTo(c + Math.cos(a) * ring, c + Math.sin(a) * ring);
        ctx.lineTo(c + Math.cos(a) * (ring + L), c + Math.sin(a) * (ring + L));
        ctx.stroke();
      }

      // waveform bars
      ctx.lineWidth = Math.max(1.2 * dpr, (2 * Math.PI * r0 / N) * 0.42);
      for (let i = 0; i < N; i++) {
        const a = -Math.PI / 2 + (i / N) * Math.PI * 2;
        let v = peaks[i] ?? 0.3;
        if (playing && !reduce) v *= 1 + 0.07 * Math.sin(now / 160 + i * 0.7);
        const r1 = r0 + 6 * dpr, L = 3 * dpr + v * maxL;
        ctx.strokeStyle = i / N < progress ? "#eaae6e" : "rgba(236,233,226,.26)";
        ctx.beginPath();
        ctx.moveTo(c + Math.cos(a) * r1, c + Math.sin(a) * r1);
        ctx.lineTo(c + Math.cos(a) * (r1 + L), c + Math.sin(a) * (r1 + L));
        ctx.stroke();
      }

      // playhead
      if (loaded === cur) {
        const a = -Math.PI / 2 + progress * Math.PI * 2;
        ctx.fillStyle = "#eaae6e";
        ctx.beginPath(); ctx.arc(c + Math.cos(a) * ring, c + Math.sin(a) * ring, 4.5 * dpr, 0, Math.PI * 2); ctx.fill();
      }
      raf = playing ? requestAnimationFrame(draw) : 0;
    }

    function select(i) {
      cur = i;
      items.forEach((li, k) => li.classList.toggle("cur", k === i));
      refreshText();
      draw(performance.now());
    }
    const play = () => audio.play().catch(() => {});
    function load() { loaded = cur; audio.src = `${ROOT}assets/audio/${TRACKS[cur].id}.mp3`; }
    function toggle(i = cur) {
      if (i !== cur) select(i);
      if (loaded !== cur) { load(); play(); }
      else if (audio.paused) play(); else audio.pause();
    }
    function refreshText() {
      const tr = TRACKS[cur];
      const playing = loaded === cur && !audio.paused;
      $("#discComposer").textContent = tr.composer;
      $("#discState").textContent = loaded === cur ? (playing ? t("audio.now") : tr.work) : t("audio.ready");
      const total = PEAKS[tr.id] ? PEAKS[tr.id].duration : 0;
      $("#discTime").textContent = `${clock(loaded === cur ? audio.currentTime : 0)} / ${clock(total)}`;
      $("#discBtn").setAttribute("aria-label", `${t(playing ? "audio.pause" : "audio.play")}: ${tr.composer}, ${tr.work}`);
      $(".audio").classList.toggle("playing", playing);
    }

    items.forEach((li, i) => $("button", li).addEventListener("click", () => toggle(i)));
    $("#discBtn").addEventListener("click", () => toggle());
    canvas.addEventListener("pointerdown", (e) => {
      const r = canvas.getBoundingClientRect();
      const x = e.clientX - r.left - r.width / 2, y = e.clientY - r.top - r.height / 2;
      if (Math.hypot(x, y) < r.width * 0.26) return;
      let a = Math.atan2(y, x) + Math.PI / 2; if (a < 0) a += Math.PI * 2;
      if (loaded !== cur) load();
      const go = () => { audio.currentTime = (a / (Math.PI * 2)) * audio.duration; play(); };
      audio.readyState >= 1 ? go() : audio.addEventListener("loadedmetadata", go, { once: true });
    });

    ["play", "pause"].forEach((ev) => audio.addEventListener(ev, () => { refreshText(); if (!raf) draw(performance.now()); }));
    audio.addEventListener("timeupdate", () => { refreshText(); if (audio.paused) draw(performance.now()); });
    audio.addEventListener("ended", () => { if (cur + 1 < TRACKS.length) toggle(cur + 1); else { loaded = -1; select(0); } });

    addEventListener("resize", resize);
    select(0);
    return { resize };
  })();

  /* ======================================================================
     IV. Gallery — filters + lightbox (tiles are plain links to the large image)
     ====================================================================== */
  (function gallery() {
    const grid = $("#grid");
    const sets = $$(".set", grid);
    const photo = (tile) => ({ name: tile.dataset.name, w: +tile.dataset.w, h: +tile.dataset.h, ext: tile.dataset.ext, tile });
    let visible = $$(".tile", grid).map(photo);

    $$("#filters button").forEach((b) => b.addEventListener("click", () => {
      const s = b.dataset.series;
      $$("#filters button").forEach((x) => x.setAttribute("aria-selected", String(x === b)));
      sets.forEach((set) => {
        set.hidden = !(s === "all" || set.dataset.series === s);
        if (!set.hidden) $$(".tile", set).forEach((tile, k) => {
          tile.classList.remove("enter"); void tile.offsetWidth;
          tile.style.animationDelay = `${Math.min(k, 12) * 0.03}s`;
          tile.classList.add("enter");
        });
      });
      visible = $$(".set:not([hidden]) .tile", grid).map(photo);
      requestAnimationFrame(onScroll);
    }));
    $$("img", grid).forEach((img) => img.complete ? img.classList.add("ok") : img.addEventListener("load", () => img.classList.add("ok"), { once: true }));

    const lb = $("#lightbox"), img = $("#lbImg");
    let idx = 0, opener = null;
    const fit = (w, h, m) => { const k = Math.min(1, m / Math.max(w, h)); return [Math.round(w * k), Math.round(h * k)]; };
    function show(i) {
      idx = (i + visible.length) % visible.length;
      const p = visible[idx];
      const [w, h] = fit(p.w, p.h, 2000);
      img.classList.add("loading");
      img.onload = () => img.classList.remove("loading");
      img.width = w; img.height = h;
      img.src = `${ROOT}assets/photos/lg/${p.name}.webp`;
      img.alt = $("img", p.tile).alt;
      $("#lbCount").textContent = `IV — ${pad(idx + 1)} / ${pad(visible.length)}`;
      $("#lbDownload").href = `${ROOT}assets/press/${p.name}.${p.ext}`;
      $("#lbDownload").setAttribute("download", `Monika-Leskovar-${p.name}.${p.ext}`);
      [idx + 1, idx - 1].forEach((n) => { new Image().src = `${ROOT}assets/photos/lg/${visible[(n + visible.length) % visible.length].name}.webp`; });
    }
    function close() { lb.hidden = true; document.body.style.overflow = ""; opener && opener.focus(); }

    grid.addEventListener("click", (e) => {
      const tile = e.target.closest(".tile");
      if (!tile || e.metaKey || e.ctrlKey || e.shiftKey) return;
      e.preventDefault();
      opener = tile;
      lb.hidden = false; document.body.style.overflow = "hidden";
      show(visible.findIndex((p) => p.tile === tile));
      $("#lbClose").focus();
    });
    $("#lbClose").addEventListener("click", close);
    $("#lbPrev").addEventListener("click", () => show(idx - 1));
    $("#lbNext").addEventListener("click", () => show(idx + 1));
    $(".lb__stage").addEventListener("click", (e) => { if (e.target === e.currentTarget) close(); });
    addEventListener("keydown", (e) => {
      if (e.key === "Escape") closeMenu();
      if (lb.hidden) return;
      if (e.key === "Escape") close();
      if (e.key === "ArrowRight") show(idx + 1);
      if (e.key === "ArrowLeft") show(idx - 1);
      if (e.key === "Tab") {
        const f = $$("button, a", lb);
        if (e.shiftKey && document.activeElement === f[0]) { e.preventDefault(); f[f.length - 1].focus(); }
        else if (!e.shiftKey && document.activeElement === f[f.length - 1]) { e.preventDefault(); f[0].focus(); }
      }
    });
    let sx = null;
    lb.addEventListener("touchstart", (e) => { sx = e.touches[0].clientX; }, { passive: true });
    lb.addEventListener("touchend", (e) => {
      if (sx === null) return;
      const dx = e.changedTouches[0].clientX - sx;
      if (Math.abs(dx) > 50) show(idx + (dx < 0 ? 1 : -1));
      sx = null;
    });
  })();

  /* ======================================================================
     Cursor (fine pointers only)
     ====================================================================== */
  if (matchMedia("(hover: hover) and (pointer: fine)").matches && !reduce) {
    const cur = $("#cursor"), label = $("#cursorLabel");
    let x = innerWidth / 2, y = innerHeight / 2, cx = x, cy = y;
    addEventListener("pointermove", (e) => { x = e.clientX; y = e.clientY; }, { passive: true });
    const loop = () => {
      cx += (x - cx) * 0.2; cy += (y - cy) * 0.2;
      cur.style.transform = `translate3d(${cx}px, ${cy}px, 0)`;
      requestAnimationFrame(loop);
    };
    loop();
    document.addEventListener("pointerover", (e) => {
      const big = e.target.closest("[data-cursor]");
      const link = !big && e.target.closest("a, button, canvas");
      cur.classList.toggle("big", !!big);
      cur.classList.toggle("link", !!link);
      if (big) label.textContent = t(`cursor.${big.dataset.cursor}`);
    });
    document.addEventListener("pointerleave", () => cur.classList.remove("big", "link"));
  }

  /* ======================================================================
     Scroll-driven bits
     ====================================================================== */
  const heroMedia = $("#heroMedia");
  const io = new IntersectionObserver((es) => es.forEach((e) => { if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); } }), { rootMargin: "0px 0px -10% 0px" });
  ["shead", "tracklist", "disc", "filters", "concerts__cols", "coda__title", "coda__mail", "coda__social", "with", "bio__more"]
    .forEach((c) => $$("." + c).forEach((el) => { el.classList.add("rv"); io.observe(el); }));

  let ticking = false;
  function onScroll() {
    if (ticking) return;
    ticking = true;
    requestAnimationFrame(() => {
      ticking = false;
      const y = scrollY;
      head.classList.toggle("scrolled", y > 30);
      head.classList.toggle("hide", y > lastY && y > innerHeight && !document.body.classList.contains("menu-open"));
      lastY = y;
      if (!reduce && y < innerHeight * 1.2) heroMedia.style.transform = `translate3d(0, ${(y * 0.28).toFixed(1)}px, 0)`;
      let active = -1;
      targets.forEach((s, i) => { if (s && s.getBoundingClientRect().top < innerHeight * 0.45) active = i; });
      navLinks.forEach((a, i) => a.classList.toggle("active", i === active));
      updateStatement();
      updateTimeline();
    });
  }

  /* ======================================================================
     Init
     ====================================================================== */
  sizeTimeline();
  Disc.resize();
  onScroll();
  addEventListener("scroll", onScroll, { passive: true });
  addEventListener("resize", () => { sizeTimeline(); onScroll(); });

  const fontsReady = document.fonts ? Promise.race([document.fonts.ready, new Promise((r) => setTimeout(r, 1200))]) : Promise.resolve();
  runIntro(() => fontsReady.then(() => {
    sizeTimeline();
    Disc.resize();
    root.classList.add("ready");
    onScroll();
  }));
})();
